function pickChampion(name){if(state.draft.length>=3)return;if(state.draft.includes(name))state.draft=state.draft.filter(n=>n!==name);else state.draft.push(name);renderDraft()}
let roundWins=[0,0],roundNo=1;
function startMatch(){if(state.draft.length<3)return;roundWins=[0,0];roundNo=1;state.matchTick=0;state.blueKills=0;state.redKills=0;state.speed=1;state.matchTimer=true;renderMatch();runTick()}
function renderMatch(){const opponent=currentOpponent();document.querySelector('#modalBody').innerHTML=`<div class="modal-head"><h2>EMBER FIVE <span style="color:var(--muted);font-weight:400">vs.</span> ${opponent.name}</h2><button class="close" onclick="leaveMatch()">×</button></div><div class="match-content"><div class="match-meta"><b>GAME ${roundNo} OF 3 <span style="color:var(--muted);font-weight:400">· BEST OF 3</span></b><span id="matchClock">00:${String(Math.min(59,state.matchTick*2)).padStart(2,'0')}</span></div><div class="arena"><div class="arena-grid"></div><div class="tower left"></div><div class="tower right"></div><div class="arena-score"><b>${roundWins[0]}</b> &nbsp; <span style="color:#7d8c8d">${state.blueKills} — ${state.redKills}</span> &nbsp; <span class="enemy-score">${roundWins[1]}</span></div><div id="units"></div><div class="arena-status" id="arenaStatus">TEAMS ARE MOVING INTO POSITION</div></div><div class="match-meta"><b>LIVE COMMS</b><span>GAME ${roundNo} · ${state.tactic.toUpperCase()}</span></div><div class="match-log" id="matchLog"><div class="log-line"><span class="log-time">00:00</span>Both teams enter the Rift. Draft locked: ${state.draft.join(', ')}.</div></div><div class="match-controls"><div class="speed-controls"><button class="on" onclick="setSpeed(1,this)">1×</button><button onclick="setSpeed(2,this)">2×</button><button onclick="setSpeed(4,this)">4×</button></div><span style="font:9px var(--mono);color:var(--muted)">AUTO-SIMULATING</span><button class="secondary" onclick="skipMatch()">SKIP TO RESULT »</button></div></div>`;drawUnits()}
function drawUnits(){const box=document.querySelector('#units');if(!box)return;const icons=['⚔','✦','◈','⬟','✧'];const tick=state.matchTick;box.innerHTML=Array.from({length:5},(_,i)=>{const allyX=14+((tick*5+i*13)%31),foeX=86-((tick*4+i*11)%31),y=26+((i*17+tick*3)%54);return `<div class="unit ally" style="left:${allyX}%;top:${y}%">${icons[i]}</div><div class="unit foe" style="left:${foeX}%;top:${100-y-12}%">${['✹','◉','❖','✶','⬢'][i]}</div>`}).join('')}
function addLog(text){const log=document.querySelector('#matchLog');if(!log)return;log.insertAdjacentHTML('beforeend',`<div class="log-line"><span class="log-time">00:${String(Math.min(59,state.matchTick*2)).padStart(2,'0')}</span>${text}</div>`);log.scrollTop=log.scrollHeight}
function setSpeed(speed,button){state.speed=speed;document.querySelectorAll('.speed-controls button').forEach(b=>b.classList.remove('on'));button.classList.add('on');if(state.matchTimer){clearInterval(state.matchTimer);state.matchTimer=setInterval(matchTick,1000/state.speed)}}
function teamPower(){const avg=state.players.reduce((a,p)=>a+p.skill+(p.form-3)*2+(p.morale-70)*.08,0)/5;let bonus=state.tactic==='aggressive'?3:state.tactic==='scaling'?1:0;bonus+=state.focus==='adapt'?2:state.focus==='teamfight'?2:1;bonus+=state.draft.reduce((a,n)=>a+(['Moss','Echo','Rook'].includes(n)?1.5:0),0);return avg+bonus}
function matchTick(){state.matchTick++;const power=teamPower();const aggression=state.tactic==='aggressive'?1.24:state.tactic==='scaling'?(state.matchTick>11?1.2:.81):1;const allyChance=Math.min(.76,.39+(power-82)*.018)*aggression;const enemyChance=.45+(Math.random()*.09);let event='';if(Math.random()<allyChance*.48){state.blueKills++;event=`${state.players[Math.floor(Math.random()*5)].name} finds an opening! Ember Five secure a takedown.`}else if(Math.random()<enemyChance*.4){state.redKills++;event=`${currentOpponent().short} strike back with a clean pick.`}else if(state.matchTick%4===0)event=state.matchTick>12?'Both teams group for the final objective.':'Teams trade vision across the map.';if(event)addLog(event);const clock=document.querySelector('#matchClock');if(clock)clock.textContent=`00:${String(Math.min(59,state.matchTick*2)).padStart(2,'0')}`;const status=document.querySelector('#arenaStatus');if(status)status.textContent=state.matchTick>13?'CONTESTING THE NEXUS':'FIGHTING FOR MAP CONTROL';const score=document.querySelector('.arena-score');if(score)score.innerHTML=`<b>${roundWins[0]}</b> &nbsp; <span style="color:#7d8c8d">${state.blueKills} — ${state.redKills}</span> &nbsp; <span class="enemy-score">${roundWins[1]}</span>`;drawUnits();if(state.blueKills>=7||state.redKills>=7||state.matchTick>=18)finishRound()}
function finishRound(){clearInterval(state.matchTimer);state.matchTimer=null;let ours=state.blueKills+(teamPower()-82)*.14+Math.random()*2;let theirs=state.redKills+Math.random()*2;if(ours===theirs)ours+=Math.random()-.5;const won=ours>theirs;roundWins[won?0:1]++;addLog(won?'EMBER FIVE destroy the Nexus! Game secured.':`${currentOpponent().short} take the game. Reset and refocus.`);if(roundWins[0]===2||roundWins[1]===2||roundNo===3){finishSeries(roundWins[0]>roundWins[1]);return}roundNo++;setTimeout(()=>{if(!document.querySelector('#modal').classList.contains('open'))return;state.matchTick=0;state.blueKills=0;state.redKills=0;renderMatch();state.matchTimer=setInterval(matchTick,1000/state.speed);addLog('Next game begins. Resetting the draft and returning to lane.')},1700)}
function finishSeries(won){clearInterval(state.matchTimer);state.matchTimer=null;state.played=true;state.lastResult=won;state.results[state.week-1]=won;if(won){state.wins++;state.cash+=1200;state.fans+=Math.floor(90+Math.random()*70);state.morale=Math.min(99,state.morale+4);state.players.forEach(p=>{p.form=Math.min(5,p.form+(Math.random()<.65?1:0));p.morale=Math.min(99,p.morale+3)})}else{state.losses++;state.cash+=550;state.fans=Math.max(500,state.fans-35);state.morale=Math.max(45,state.morale-5);state.players.forEach(p=>{p.form=Math.max(1,p.form-(Math.random()<.4?1:0));p.morale=Math.max(45,p.morale-3)})}render();const opponent=currentOpponent();document.querySelector('#modalBody').innerHTML=`<div class="modal-head"><h2>Series complete <span style="color:var(--muted);font-weight:400">/ Week ${state.week}</span></h2><button class="close" onclick="closeModal()">×</button></div><div class="result-banner"><div class="result-icon">${won?'🏆':'💥'}</div><div class="eyebrow">${won?'MATCH VICTORY':'MATCH DEFEAT'}</div><h2 style="color:${won?'var(--lime)':'var(--red)'}">${won?'EMBER FIVE TAKE THE SERIES':'A TOUGH SERIES'}</h2><p>EMBER FIVE ${roundWins[0]} — ${roundWins[1]} ${opponent.name}</p><div class="result-stats"><div><b>${won?'+1,200':' +550'}</b>PRIZE MONEY</div><div><b>${won?'+3':'—'}</b>LEAGUE POINTS</div><div><b>${fmt(state.fans)}</b>FANS</div></div><button class="primary" onclick="closeModal()">BACK TO CLUBHOUSE →</button></div>`;save()}
function skipMatch(){if(!state.matchTimer)return;while(state.matchTimer){matchTick()} }
function leaveMatch(){if(state.matchTimer){if(!confirm('Leave the live match? Your current game will be forfeited.'))return;clearInterval(state.matchTimer);state.matchTimer=null;finishSeries(false);return}closeModal()}
function advanceWeek(){if(state.week>=10){state.week=1;state.wins=0;state.losses=0;state.results=[];state.fans+=300;state.cash+=2500;toast('Split complete! New season begins. +◈2,500');}else{state.week++;state.played=false;state.cash=Math.max(0,state.cash-state.players.reduce((a,p)=>a+p.salary,0));state.focus='adapt';}render();if(state.week>1)toast(`Week ${state.week} begins · player salaries paid`)}
load();render();
</script>
</body>
</html>

