 function rankOf(short){return leagueData().findIndex(entry=>entry.team.short===short)+1}
 function ordinal(n){return n+(n%100>=11&&n%100<=13?'th':({1:'st',2:'nd',3:'rd'}[n%10]||'th'))}
 function standingRows(){return leagueData().map((entry,i)=>`<div class="standing-row ${entry.team.short==='EMB'?'you':''}"><span class="standing-rank">${String(i+1).padStart(2,'0')}</span><span class="standing-name">${entry.team.short==='EMB'?'✦ ':''}${entry.team.name}</span><span class="standing-record">${entry.wins}-${entry.losses}</span><span class="standing-points">${entry.points}</span></div>`).join('')}
